function assert(condition: unknown, message: string): void {
  if (!condition) {
    throw new Error(message);
  }
}

const ALLOWED_HOSTS = new Set(["runtime.example.com"]);
const ALLOWED_PATH_PREFIX = "/static/hyperframes-runtime/";

function isAllowedRuntimeUrl(candidate: string): boolean {
  try {
    const parsed = new URL(candidate);
    return (
      parsed.protocol === "https:" &&
      ALLOWED_HOSTS.has(parsed.hostname.toLowerCase()) &&
      parsed.pathname.startsWith(ALLOWED_PATH_PREFIX) &&
      parsed.pathname.endsWith(".js")
    );
  } catch {
    return false;
  }
}

function isGuardedPreviewMessage(data: unknown): boolean {
  if (!data || typeof data !== "object") {
    return false;
  }
  const record = data as { source?: unknown; type?: unknown };
  const source = typeof record.source === "string" ? record.source : null;
  const type = typeof record.type === "string" ? record.type : null;
  const guardedTypes = new Set([
    "state",
    "timeline",
    "element-picked",
    "element-picked-many",
    "element-pick-candidates",
    "pick-mode-cancelled",
  ]);
  if (!type || !guardedTypes.has(type)) {
    return false;
  }
  return source === "hf-preview";
}

const allowedRuntimeFixtures = [
  "https://runtime.example.com/static/hyperframes-runtime/hyperframe.runtime.iife.js",
  "https://runtime.example.com/static/hyperframes-runtime/v2026.02.20/hyperframe.runtime.iife.js",
];

const blockedRuntimeFixtures = [
  "http://runtime.example.com/static/hyperframes-runtime/hyperframe.runtime.iife.js",
  "javascript:alert(1)",
  "data:text/javascript,alert(1)",
  "https://evil.example/static/hyperframes-runtime/hyperframe.runtime.iife.js",
  "https://runtime.example.com/static/other/hyperframe.runtime.iife.js",
  "https://runtime.example.com/static/hyperframes-runtime/hyperframe.runtime.iife.css",
];

for (const fixture of allowedRuntimeFixtures) {
  assert(isAllowedRuntimeUrl(fixture), `Expected runtime URL to be allowed: ${fixture}`);
}

for (const fixture of blockedRuntimeFixtures) {
  assert(!isAllowedRuntimeUrl(fixture), `Expected runtime URL to be blocked: ${fixture}`);
}

const allowedMessages = [
  { type: "state", source: "hf-preview" },
  { type: "timeline", source: "hf-preview" },
  { type: "element-picked", source: "hf-preview" },
];
const blockedMessages = [
  { type: "state", source: "hf-parent" },
  { type: "timeline", source: "evil-origin" },
  { type: "element-picked", source: "hf-parent" },
  { type: "pick-mode-cancelled", source: null },
  { type: "unknown-type", source: "hf-preview" },
];

for (const fixture of allowedMessages) {
  assert(
    isGuardedPreviewMessage(fixture),
    `Expected message fixture to pass guard: ${JSON.stringify(fixture)}`,
  );
}

for (const fixture of blockedMessages) {
  assert(
    !isGuardedPreviewMessage(fixture),
    `Expected message fixture to fail guard: ${JSON.stringify(fixture)}`,
  );
}

console.log(
  JSON.stringify({
    event: "hyperframe_runtime_security_fixtures_verified",
    allowedRuntimeFixtures: allowedRuntimeFixtures.length,
    blockedRuntimeFixtures: blockedRuntimeFixtures.length,
    allowedMessages: allowedMessages.length,
    blockedMessages: blockedMessages.length,
  }),
);

import { describe, expect, it } from "vitest";
import { assertSafeTarget } from "./installer.js";

const DEST = "/tmp/hf-install-test";

describe("assertSafeTarget", () => {
  it("allows simple relative paths", () => {
    expect(() => assertSafeTarget(DEST, "index.html")).not.toThrow();
    expect(() => assertSafeTarget(DEST, "compositions/intro.html")).not.toThrow();
    expect(() => assertSafeTarget(DEST, "assets/nested/deep/file.svg")).not.toThrow();
  });

  it("rejects `..` path segments", () => {
    expect(() => assertSafeTarget(DEST, "../escape.html")).toThrow(/\.\./);
    expect(() => assertSafeTarget(DEST, "compositions/../../escape.html")).toThrow(/\.\./);
    expect(() => assertSafeTarget(DEST, "a/b/../../../escape.html")).toThrow();
  });

  it("rejects Unix absolute paths", () => {
    expect(() => assertSafeTarget(DEST, "/etc/passwd")).toThrow(/absolute/);
    expect(() => assertSafeTarget(DEST, "/home/user/file.txt")).toThrow();
  });

  it("rejects Windows drive-letter paths", () => {
    expect(() => assertSafeTarget(DEST, "C:/Windows/System32")).toThrow(/Windows/);
    expect(() => assertSafeTarget(DEST, "D:\\notes.txt")).toThrow();
  });

  it("allows `.` segments (no-op) and dotfile-like names", () => {
    expect(() => assertSafeTarget(DEST, ".hidden")).not.toThrow();
    expect(() => assertSafeTarget(DEST, "./file.html")).not.toThrow();
    expect(() => assertSafeTarget(DEST, "a..b/file.html")).not.toThrow();
  });
});

/**
 * Browser integration test for fitTextFontSize.
 *
 * Launches headless Chrome, loads the runtime IIFE into a page,
 * and verifies that window.__hyperframes.fitTextFontSize produces
 * correct results with real canvas measureText.
 *
 * Requires: puppeteer (dep of @hyperframes/engine)
 * Run: cd packages/engine && npx tsx scripts/test-fitTextFontSize-browser.ts
 */

import { buildHyperframesRuntimeScript } from "../../core/src/inline-scripts/hyperframesRuntime.engine";

function assert(condition: unknown, message: string): void {
  if (!condition) {
    throw new Error(`FAIL: ${message}`);
  }
}

async function main() {
  // Dynamic import — puppeteer is a monorepo dep, not a core dep
  let puppeteer;
  try {
    puppeteer = (await import("puppeteer")).default;
  } catch {
    console.log(
      JSON.stringify({
        event: "fitTextFontSize_browser_test_skipped",
        reason: "puppeteer not available",
      }),
    );
    return;
  }

  const runtimeSource = buildHyperframesRuntimeScript({ minify: false });

  const html = `<!DOCTYPE html>
<html><head>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@900&display=block');
</style>
</head><body>
<script>${runtimeSource}</script>
<script>
  window.__testResults = {};

  // Test 1: Short text should fit at base size
  var r1 = window.__hyperframes.fitTextFontSize("HI");
  window.__testResults.shortText = r1;

  // Test 2: Wide text should shrink below base size but still fit at 1600px
  var r2 = window.__hyperframes.fitTextFontSize(
    "CONGRATULATIONS TO EVERYBODY IN THE WORLD",
    { fontFamily: "sans-serif", fontWeight: 900, maxWidth: 1600 }
  );
  window.__testResults.wideText = r2;

  // Test 3: Extremely wide text that can't fit should return minFontSize
  var r3 = window.__hyperframes.fitTextFontSize(
    "WWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWW",
    { fontFamily: "sans-serif", fontWeight: 900, maxWidth: 400 }
  );
  window.__testResults.extremeText = r3;

  // Test 4: Function exists and is callable
  window.__testResults.exists = typeof window.__hyperframes.fitTextFontSize === "function";
</script>
</body></html>`;

  const browser = await puppeteer.launch({
    headless: true,
    args: ["--no-sandbox", "--disable-setuid-sandbox"],
  });

  try {
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: "networkidle0", timeout: 10000 });

    // Wait for font to potentially load (best effort — sans-serif fallback is fine for testing)
    await new Promise((r) => setTimeout(r, 1000));

    const results = await page.evaluate(() => (window as any).__testResults);

    // Test 1: Short text fits at base size (78px default)
    assert(results.exists === true, "fitTextFontSize should exist on window.__hyperframes");
    assert(
      results.shortText.fits === true,
      `Short text should fit, got fits=${results.shortText.fits}`,
    );
    assert(
      results.shortText.fontSize === 78,
      `Short text should use base size 78, got ${results.shortText.fontSize}`,
    );

    // Test 2: Wide text should shrink below base size
    assert(
      results.wideText.fits === true,
      `Wide text should still fit, got fits=${results.wideText.fits}`,
    );
    assert(
      results.wideText.fontSize < 78,
      `Wide text should shrink below 78, got ${results.wideText.fontSize}`,
    );

    // Test 3: Extreme text should hit floor
    assert(
      results.extremeText.fontSize === 42,
      `Extreme text should hit minFontSize 42, got ${results.extremeText.fontSize}`,
    );
    assert(
      results.extremeText.fits === false,
      `Extreme text should not fit, got fits=${results.extremeText.fits}`,
    );

    console.log(
      JSON.stringify({
        event: "fitTextFontSize_browser_test_passed",
        shortText: results.shortText,
        wideText: results.wideText,
        extremeText: results.extremeText,
      }),
    );
  } finally {
    await browser.close();
  }
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

import { Hono } from "hono";
import type { StudioApiAdapter } from "./types.js";
import { registerProjectRoutes } from "./routes/projects.js";
import { registerFileRoutes } from "./routes/files.js";
import { registerPreviewRoutes } from "./routes/preview.js";
import { registerLintRoutes } from "./routes/lint.js";
import { registerRenderRoutes } from "./routes/render.js";
import { registerThumbnailRoutes } from "./routes/thumbnail.js";

/**
 * Create a Hono sub-app with all studio API routes.
 *
 * Both the vite dev server and CLI embedded server mount this app
 * under /api, each providing their own adapter for host-specific behavior.
 */
export function createStudioApi(adapter: StudioApiAdapter): Hono {
  const api = new Hono();

  registerProjectRoutes(api, adapter);
  registerFileRoutes(api, adapter);
  registerPreviewRoutes(api, adapter);
  registerLintRoutes(api, adapter);
  registerRenderRoutes(api, adapter);
  registerThumbnailRoutes(api, adapter);

  return api;
}

import { describe, it, expect, vi } from "vitest";
import { createWaapiAdapter } from "./waapi";

describe("waapi adapter", () => {
  it("has correct name", () => {
    expect(createWaapiAdapter().name).toBe("waapi");
  });

  it("seek pauses and sets currentTime on all animations", () => {
    const mockAnim = { pause: vi.fn(), currentTime: 0 };
    (document as any).getAnimations = vi.fn(() => [mockAnim]);

    const adapter = createWaapiAdapter();
    adapter.seek({ time: 2.5 });

    expect(mockAnim.pause).toHaveBeenCalled();
    expect(mockAnim.currentTime).toBe(2500); // seconds → ms

    delete (document as any).getAnimations;
  });

  it("seek clamps negative time to 0", () => {
    const mockAnim = { pause: vi.fn(), currentTime: 0 };
    (document as any).getAnimations = vi.fn(() => [mockAnim]);

    const adapter = createWaapiAdapter();
    adapter.seek({ time: -3 });

    expect(mockAnim.currentTime).toBe(0);
    delete (document as any).getAnimations;
  });

  it("pause pauses all animations", () => {
    const mockAnim = { pause: vi.fn(), currentTime: 0 };
    (document as any).getAnimations = vi.fn(() => [mockAnim]);

    const adapter = createWaapiAdapter();
    adapter.pause();

    expect(mockAnim.pause).toHaveBeenCalled();
    delete (document as any).getAnimations;
  });

  it("handles missing getAnimations API", () => {
    const original = document.getAnimations;
    (document as Record<string, unknown>).getAnimations = undefined;

    const adapter = createWaapiAdapter();
    expect(() => adapter.seek({ time: 1 })).not.toThrow();
    expect(() => adapter.pause()).not.toThrow();

    document.getAnimations = original;
  });

  it("handles animation that throws on pause", () => {
    const mockAnim = {
      pause: vi.fn(() => {
        throw new Error("invalid state");
      }),
      currentTime: 0,
    };
    (document as any).getAnimations = vi.fn(() => [mockAnim]);

    const adapter = createWaapiAdapter();
    expect(() => adapter.seek({ time: 1 })).not.toThrow();

    delete (document as any).getAnimations;
  });

  it("discover is a no-op", () => {
    const adapter = createWaapiAdapter();
    expect(() => adapter.discover()).not.toThrow();
  });
});

// @vitest-environment node
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { buildSubCompositionHtml } from "./subComposition";

function makeTempProject(files: Record<string, string>): string {
  const dir = mkdtempSync(join(tmpdir(), "hf-subcomp-preview-"));
  for (const [rel, content] of Object.entries(files)) {
    const full = join(dir, rel);
    mkdirSync(join(full, ".."), { recursive: true });
    writeFileSync(full, content, "utf-8");
  }
  return dir;
}

describe("buildSubCompositionHtml", () => {
  it("rewrites sub-composition asset paths against the project root preview base", () => {
    const dir = makeTempProject({
      "index.html": `<!doctype html>
<html><head><title>Test</title></head><body></body></html>`,
      "compositions/hero.html": `<template id="hero-template">
  <div data-composition-id="hero" data-width="1920" data-height="1080">
    <img src="../logo.png" alt="Logo" />
    <style>
      @font-face {
        font-family: "Brand Sans";
        src: url("../fonts/brand.woff2") format("woff2");
      }
    </style>
  </div>
</template>`,
    });

    const html = buildSubCompositionHtml(
      dir,
      "compositions/hero.html",
      "/api/runtime.js",
      "/api/projects/demo/preview/",
    );

    expect(html).toContain('<base href="/api/projects/demo/preview/">');
    expect(html).toContain('src="logo.png"');
    expect(html).toContain('url("fonts/brand.woff2")');
    expect(html).not.toContain('src="../logo.png"');
    expect(html).not.toContain('url("../fonts/brand.woff2")');
  });
});

